def add_toc_item(self, tokens, idx):

    """
    This function adds a TOC item into the state.env.
    Input-Output Arguments
    :param tokens: List. The tokens of the current line.
    :param idx: Integer. The index of the current line.
    :return: No return values.
    """

    if tokens[idx][0] == "heading_open":
        level = int(tokens[idx][1][1])
        if min_level <= level <= max_level:
            if "id" not in tokens[idx][1]:
                if heading_id is None:
                    tokens[idx][1]["id"] = striptags(tokens[idx + 1][0]).lower().replace(" ", "-")
                else:
                    tokens[idx][1]["id"] = heading_id(tokens[idx + 1][0])
            self.env["toc"].append({
                "level": level,
                "title": tokens[idx + 1][0],
                "id": tokens[idx][1]["id"]
            })

