    if heading_id is None:
        heading_id = lambda label, level: label.lower().replace(" ", "-")
    if tokens[0].get("level") is not None:
        level = tokens[0].get("level")
        if min_level <= level <= max_level:
            label = striptags(tokens[0].get("text"))
            if "toc" not in md.env:
                md.env["toc"] = []
            md.env["toc"].append({"label": label, "level": level, "id": heading_id(label, level)})

md.pre_render.append(_add_toc_hook)

