    if block.tag in ('h1', 'h2', 'h3', 'h4', 'h5', 'h6'):
        level = int(block.tag[1])
        text = striptags(block.children[0].children[0].text)
        slug = block.attributes.get('id', text)
        add_toc_item_wrapper(level, text, slug)

