def add_toc_item(self, tokens):
    level = tokens[0].get("level", 0)
    if level >= min_level and level <= max_level:
        text = striptags(tokens[0].get("text"))
        if heading_id:
            heading_id = heading_id(text)
        else:
            heading_id = text.lower().replace(" ", "-")
        self.env.toc_items.append((level, text, heading_id))

md.inline_types.append("toc_item")
md.inline_rules["toc_item"] = add_toc_item

def _toc_hook(md):
    env = md.env
    if not hasattr(env, 'toc'):
        env.toc = []
    if not hasattr(env, 'toc_counter'):
        env.toc_counter = {}
    if not hasattr(env, 'toc_ids'):
        env.toc_ids = {}

    def _toc_id(label):
        label = label.lower()
        if label in env.toc_ids:
            env.toc_ids[label] += 1
            return label + '-' + str(env.toc_ids[label])
        env.toc_ids[label] = 1
        return label

    if heading_id:
        _toc_id = heading_id

    def _toc_item(level, text, slug):
        if level >= min_level and level <= max_level:
            if level not in env.toc_counter:
                env.toc_counter[level] = 1
            else:
                env.toc_counter[level] += 1
            title = '.' * (level - 1) + str(env.toc_counter[level]) + '. ' + text
            env.toc.append((level, title, slug))

    def _toc_open(md, tokens, idx, **kwargs):
        token = tokens[idx]
        if token['name'] in ['h1', 'h2', 'h3', 'h4', 'h5', 'h6']:
            text = striptags(md.htmlStash.rawHtmlTags, token['children'][0]['content'])
            slug = _toc_id(text)
            _toc_item(int(token['name'][1]), text, slug)
            token['attributes'] = {'id': slug}

    md.preprocessors.register(_toc_open, 'toc', 45)

md.register_preprocessor('toc', _toc_hook)

def _toc_hook(self, md):

    self.env['toc'] = []

    def _toc_insert(self, level, text, slug):

        if level < min_level or level > max_level:
            return
        self.env['toc'].append({
            'level': level,
            'text': text,
            'slug': slug,
        })

    md.register_plugin('toc', _toc_insert)

md.use(_toc_hook)

