# If the last token is a keyword, return the value of the last keyword and the text of the query with everything after the last keyword stripped
if last_token.is_keyword:
    return last_token.value, str(parsed.tokens[:-1 - n_skip])

# If the last token is an identifier, return the value of the last identifier and the text of the query with everything after the last identifier stripped
if isinstance(last_token, Identifier):
    return last_token.value, str(parsed.tokens[:-1 - n_skip])

# If the last token is an error token, return the value of the last token and the text of the query with everything after the last token stripped
if isinstance(last_token, Error):
    return last_token.value, str(parsed.tokens[:-1 - n_skip])

# If the last token is a token, return the value of the last token and the text of the query with everything after the last token stripped
if isinstance(last_token, Token):
    return last_token.value, str(parsed.tokens[:-1 - n_skip])

# If the last token is not a keyword, identifier, error token, or token, return None and the original query
return None, sql

