def _generate_paragraph(n_words: int) -> str:
    words = []
    for _ in range(n_words):
        word = choice(cache.get("lorem_words"))
        if len(words) % randrange(3, 9) == 0:
            word += ","
        elif len(words) % randrange(10, 21) == 0:
            word += "."
        words.append(word)
    return " ".join(words)

