if state and not is_base64_string(state):
    state = urlsafe_base64_encode(state)

url = parse_url(uri)
if url.fragment:
    params = parse_qs(url.fragment)
else:
    params = parse_qs(url.query)

if 'error' in params:
    raise Exception(params['error'])

if 'code' not in params:
    raise MissingCodeException()

code = params['code']
if len(code) > 1:
    raise Exception('Multiple codes found')
code = code[0]

if state and 'state' not in params:
    raise MismatchingStateException()

if state and 'state' in params:
    if not constant_time_compare(state, params['state']):
        raise MismatchingStateException()

if 'error_description' in params:
    raise Exception(params['error_description'])

if 'error_uri' in params:
    raise Exception(params['error_uri'])

return {
    'code': code,
    'state': params.get('state')
}

query = urlparse.urlparse(uri).fragment
params = dict(urlparse.parse_qsl(query))
if 'access_token' not in params:
    raise MissingException('access_token')
if 'token_type' not in params:
    raise MissingException('token_type')
if 'expires_in' not in params:
    raise MissingException('expires_in')
if 'scope' not in params:
    raise MissingException('scope')
if state and params.get('state') != state:
    raise MismatchingStateException()
return params

