    :param parent: Optional[SchemaItem]. The parent item of the schema item being compared.
    :return: Any. The return format is a list of "diff" directives representing the differences between the two items.
    """
    if isinstance(item, inspect(util.ImplicitComparator).mapped_class):
        return item.compare_self(context)
