        logger.debug(f"Processing {name}")

        # Get artifacts from source.
        artifacts = source.get_artifacts()
        if not artifacts:
            logger.debug(f"No artifacts from {name}")
            continue

        logger.debug(f"{len(artifacts)} artifacts from {name}")
        for artifact in artifacts:
            if self._is_whitelisted(artifact):
                continue

            # Check if artifact is new.
            if self.statedb.is_new(artifact):
                logger.debug(f"New artifact from {name}: {str(artifact)}")
                self.statedb.add(artifact)

                # Send artifact to operators.
                for name, operator in self.operators.items():
                    try:
                        operator.send(artifact)
                    except (threatingestor.exceptions.PluginError, ConnectionError):
                        logger.exception(f"Error sending to {name}")

            else:
                logger.debug(f"Duplicate artifact from {name}: {str(artifact)}")

    # Sleep for configured interval.
    if self.config.daemon():
        logger.info(f"Sleeping for {self.config.interval()} seconds")
        time.sleep(self.config.interval())
    else:
        logger.info("Ingestor run complete")
        break

