while True:
    logger.debug("Running sources")
    for source in self.sources.values():
        logger.debug(f"Running source '{source.name()}'")
        try:
            source.run()
        except threatingestor.exceptions.SourceError as e:
            logger.exception(f"Error running source '{source.name()}'")
            self.statsd.incr(f"source.{source.name()}.error")
            self.statsd.incr("source.error")
            continue

        logger.debug(f"Source '{source.name()}' returned {len(source.artifacts())} artifacts")
        self.statsd.incr(f"source.{source.name()}.count", len(source.artifacts()))
        self.statsd.incr("source.count", len(source.artifacts()))

        logger.debug(f"Running operators for source '{source.name()}'")
        for artifact in source.artifacts():
            if self._is_whitelisted(artifact):
                continue

            logger.debug(f"Running operators for artifact '{str(artifact)}'")
            for operator in self.operators.values():
                try:
                    operator.run(artifact)
                except threatingestor.exceptions.OperatorError as e:
                    logger.exception(f"Error running operator '{operator.name()}'")
                    self.statsd.incr(f"operator.{operator.name()}.error")
                    self.statsd.incr("operator.error")
                    continue

                logger.debug(f"Operator '{operator.name()}' processed artifact '{str(artifact)}'")
                self.statsd.incr(f"operator.{operator.name()}.count")
                self.statsd.incr("operator.count")

    logger.debug("Sleeping")
    if self.config.daemon():
        time.sleep(self.config.interval())
    else:
        break

