def merge(left, right):
    """
    Merges two lists into a single sorted list.
    Input-Output Arguments
    :param left: list. A list of elements.
    :param right: list. A list of elements.
    :return: list. A list of elements.
    """
    if len(left) == 0:
        return right
    if len(right) == 0:
        return left
    if left[0] < right[0]:
        return [left[0]] + merge(left[1:], right)
    return [right[0]] + merge(left, right[1:])

def merge_sort(lists):
    """
    Sorts a list of lists.
    Input-Output Arguments
    :param lists: list. A list of lists.
    :return: list. A list of lists.
    """
    if len(lists) == 1:
        lists[0].sort()
        return lists
    mid = len(lists) // 2
    return merge(merge_sort(lists[:mid]), merge_sort(lists[mid:]))

